["Memnunum ama şaşırmadım."] = "MEMNUNUM AMA ŞAŞIRMADIM.",
["Mendoza ailesi, Cobra ailesine büyük ligde oynamanın ne demek olduğunu göstermek istiyor. Rats’in 2. gününde onlara dört metamfetamin çantası götür ama ödeme parasını almak yerine çal."] = "MENDOZA AİLESİ, COBRA AİLESİNE BÜYÜK LİGDE OYNAMANIN NE DEMEK OLDUĞUNU GÖSTERMEK İSTİYOR. RATS’İN 2. GÜNÜNDE ONLARA DÖRT METAMFETAMİN ÇANTASI GÖTÜR AMA ÖDEME PARASINI ALMAK YERİNE ÇAL.",
["Mendoza ailesinin ileri gelenleri hepinizin ölümüne yemin etti... Bu, kartelimizin ABD'deki geleceğinde önemli bir etki yarattığınızın iyi bir işareti. Her şey için çok teşekkürler çocuklar..."] = "MENDOZA AİLESİNİN İLERİ GELENLERİ HEPİNİZİN ÖLÜMÜNE YEMİN ETTİ... BU, KARTELİMİZİN ABD'DEKİ GELECEĞİNDE ÖNEMLİ BİR ETKİ YARATTIĞINIZIN İYİ BİR İŞARETİ. HER ŞEY İÇİN ÇOK TEŞEKKÜRLER ÇOCUKLAR...",
["Mendoza bu sonuçtan hoşlanmayacak. Biz hoşlanmalıyız ama. Aferin. Gidip paranızı alın."] = "MENDOZA BU SONUÇTAN HOŞLANMAYACAK. BİZ HOŞLANMALIYIZ AMA. AFERİN. GİDİP PARANIZI ALIN.",
["Mendoza hakkındaki bilgileri al"] = "MENDOZA HAKKINDAKİ BİLGİLERİ AL",
["Mendoza karteli D.C.'deki metamfetamin operasyonumuza saldırıyor. Ya cesaretlendiler ya da çaresiz kaldılar. Oraya gidin, pişman edin onları."] = "MENDOZA KARTELİ D.C.'DEKİ METAMFETAMİN OPERASYONUMUZA SALDIRIYOR. YA CESARETLENDİLER YA DA ÇARESİZ KALDILAR. ORAYA GİDİN, PİŞMAN EDİN ONLARI.",
["Mendoza karteli az önce kıçının üstüne oturtuldu. Maddi darbe kadar can yakan bir şey yoktur, büyük darbe aldılar. Hector yükselecek, bu da ileride bizim için iyi şans demek."] = "MENDOZA KARTELİ AZ ÖNCE KIÇININ ÜSTÜNE OTURTULDU. MADDİ DARBE KADAR CAN YAKAN BİR ŞEY YOKTUR, BÜYÜK DARBE ALDILAR. HECTOR YÜKSELECEK, BU DA İLERİDE BİZİM İÇİN İYİ ŞANS DEMEK.",
["Mendoza karteli bizi tehdit ediyor. Ama bu şehir bizim. Güç burada ve onu biz kontrol ediyoruz. Asıl tehdidin kim olduğunu göstereceğiz."] = "MENDOZA KARTELİ BİZİ TEHDİT EDİYOR. AMA BU ŞEHİR BİZİM. GÜÇ BURADA VE ONU BİZ KONTROL EDİYORUZ. ASIL TEHDİDİN KİM OLDUĞUNU GÖSTERECEĞİZ.",
["Mendoza karteli, DC üzerinden yığınla silah geçiriyor. Buradaki silah depolarından birini vurup askerlerini zayıflatmanızı istiyoruz."] = "MENDOZA KARTELİ, DC ÜZERİNDEN YIĞINLA SİLAH GEÇİRİYOR. BURADAKİ SİLAH DEPOLARINDAN BİRİNİ VURUP ASKERLERİNİ ZAYIFLATMANIZI İSTİYORUZ.",
["Mendoza karteli, ormandaki met laboratuvarımıza saldırıyor. Acımasızlar ama aptallar. Ne kadar yanlış yaptıklarını göstereceğiz."] = "MENDOZA KARTELİ, ORMANDAKİ MET LABORATUVARIMIZA SALDIRIYOR. ACIMASIZLAR AMA APTALLAR. NE KADAR YANLIŞ YAPTIKLARINI GÖSTERECEĞİZ.",
["Mendoza kartelinin ABD'deki geleceği sona erdi. Hepsi sizin sayenizde. Buralarda herkes sizi konuşuyor. Teşekkür ederim."] = "MENDOZA KARTELİNİN ABD'DEKİ GELECEĞİ SONA ERDİ. HEPSİ SİZİN SAYENİZDE. BURALARDA HERKES SİZİ KONUŞUYOR. TEŞEKKÜR EDERİM.",
["Mendoza mangalı gürültülü bir başarıydı. Hector'ı görme vakti."] = "MENDOZA MANGALI GÜRÜLTÜLÜ BİR BAŞARIYDI. HECTOR'I GÖRME VAKTİ.",
["Mendoza'lar aşağıda. Çiti kesip o silahları alın."] = "MENDOZA'LAR AŞAĞIDA. ÇİTİ KESİP O SİLAHLARI ALIN.",
["Mendoza'lar depoda silah yüklemekle meşgul olacak. Lord of War'a bağlamadan içeri girip hızlıca vurun. Silahları alın ya da yok edin. "] = "MENDOZA'LAR DEPODA SİLAH YÜKLEMEKLE MEŞGUL OLACAK. LORD OF WAR'A BAĞLAMADAN İÇERİ GİRİP HIZLICA VURUN. SİLAHLARI ALIN YA DA YOK EDİN. ",
["Mendoza'lar havaalanına gidiyor. O evrak çantasını getirin. Eminim onunla yapacak bir şey buluruz."] = "MENDOZA'LAR HAVAALANINA GİDİYOR. O EVRAK ÇANTASINI GETİRİN. EMİNİM ONUNLA YAPACAK BİR ŞEY BULURUZ.",
["Mendoza'lar jetle kaçmak üzere. Bu malı onlar hakkında bilgiyle takas etmeliyiz. Bu adamlar pislik ama onlarla uğraşmak istemezsiniz. "] = "MENDOZA'LAR JETLE KAÇMAK ÜZERE. BU MALI ONLAR HAKKINDA BİLGİYLE TAKAS ETMELİYİZ. BU ADAMLAR PİSLİK AMA ONLARLA UĞRAŞMAK İSTEMEZSİNİZ. ",
["Mendoza'lar ülkeden uçup gitmeden yetişmemiz gerek."] = "MENDOZA'LAR ÜLKEDEN UÇUP GİTMEDEN YETİŞMEMİZ GEREK.",
["Mendoza'ların ABD'deki parası yok oldu. İyi iş çıkardınız. Tabii burada durmayacağız. Sizi yeniden arayacağım."] = "MENDOZA'LARIN ABD'DEKİ PARASI YOK OLDU. İYİ İŞ ÇIKARDINIZ. TABİİ BURADA DURMAYACAĞIZ. SİZİ YENİDEN ARAYACAĞIM.",
["Mendoza'ların kaçtığını biliyoruz. Misilleme için bize son bir saldırı yapıyorlar gibi. Met laboratuvarımız saldırı altında. Meti ve aşçıları kurtarın. Düşmana nasıl davranılacağını biliyorsunuz. Yapın."] = "MENDOZA'LARIN KAÇTIĞINI BİLİYORUZ. MİSİLLEME İÇİN BİZE SON BİR SALDIRI YAPIYORLAR GİBİ. MET LABORATUVARIMIZ SALDIRI ALTINDA. METİ VE AŞÇILARI KURTARIN. DÜŞMANA NASIL DAVRANILACAĞINI BİLİYORSUNUZ. YAPIN.",
["Mendoza'ların nakit akışı hakkında bilgimiz var. Amerika'daki operasyonlarından 100 milyon doların üzerinde kazanıyorlar. Bir mesaj vermek istiyoruz: Paraları da silahları da artık bir işe yaramıyor."] = "MENDOZA'LARIN NAKİT AKIŞI HAKKINDA BİLGİMİZ VAR. AMERİKA'DAKİ OPERASYONLARINDAN 100 MİLYON DOLARIN ÜZERİNDE KAZANIYORLAR. BİR MESAJ VERMEK İSTİYORUZ: PARALARI DA SİLAHLARI DA ARTIK BİR İŞE YARAMIYOR.",
["Mendoza'ların nakit akışı tamamen dursun istiyoruz. Bütün nakit rezervleri burada, DC'de. Ulaşmak için silah depolarını yok edip askerlerini silahsız bırakmalıyız."] = "MENDOZA'LARIN NAKİT AKIŞI TAMAMEN DURSUN İSTİYORUZ. BÜTÜN NAKİT REZERVLERİ BURADA, DC'DE. ULAŞMAK İÇİN SİLAH DEPOLARINI YOK EDİP ASKERLERİNİ SİLAHSIZ BIRAKMALIYIZ.",
["Mendoza'nın adamları orada pişiriyor. Onları temizleyip Hector'ın metini geri alın. Malı alınca buradan çıkabilirsiniz. Başlayın."] = "MENDOZA'NIN ADAMLARI ORADA PİŞİRİYOR. ONLARI TEMİZLEYİP HECTOR'IN METİNİ GERİ ALIN. MALI ALINCA BURADAN ÇIKABİLİRSİNİZ. BAŞLAYIN.",
["Mendoza'nın örgütüne çiviler çaktık. Bize yapacakları gibi onları çarmıha gerdik. Maaş yoksa örgüt de yok. FBI'ın pençesi gevşiyor, Mendoza'lar mevzi kaybediyor."] = "MENDOZA'NIN ÖRGÜTÜNE ÇİVİLER ÇAKTIK. BİZE YAPACAKLARI GİBİ ONLARI ÇARMIHA GERDİK. MAAŞ YOKSA ÖRGÜT DE YOK. FBI'IN PENÇESİ GEVŞİYOR, MENDOZA'LAR MEVZİ KAYBEDİYOR.",
["Menzil"] = "MENZİL",
["Menü"] = "MENÜ",
["Menülerde"] = "MENÜLERDE",
