["Merhaba beyler. Müşterimiz bu işi bizimle yapmayı kabul etmenizden çok memnun. Ama şunu bilin; bu işin gerçekleşmesinin tek yolu bizim dediğimiz gibi yapılması."] = "MERHABA BEYLER. MÜŞTERİMİZ BU İŞİ BİZİMLE YAPMAYI KABUL ETMENİZDEN ÇOK MEMNUN. AMA ŞUNU BİLİN; BU İŞİN GERÇEKLEŞMESİNİN TEK YOLU BİZİM DEDİĞİMİZ GİBİ YAPILMASI.",
["Merhaba dostlar."] = "MERHABA DOSTLAR.",
["Merhaba dostlar. Seçtiğim atlayış noktasına neredeyse geldiniz. Lütfen dışarı çıkıp sizin deyişinizle partiyi başlatın."] = "MERHABA DOSTLAR. SEÇTİĞİM ATLAYIŞ NOKTASINA NEREDEYSE GELDİNİZ. LÜTFEN DIŞARI ÇIKIP SİZİN DEYİŞİNİZLE PARTİYİ BAŞLATIN.",
["Merhaba dostlarım, küçük bir iyilik isteyeceğim..."] = "MERHABA DOSTLARIM, KÜÇÜK BİR İYİLİK İSTEYECEĞİM...",
["Merhaba dostlarım. Umarım burayı doğru düzgün toparlayacak vaktimiz olmamasını hoş görürsünüz. Buraya temizlik ekibi getirmek oldukça zor, anlarsınız. İnanın bana, bu ziyaretinizi hiçbir şekilde kişisel algılamıyorum."] = "MERHABA DOSTLARIM. UMARIM BURAYI DOĞRU DÜZGÜN TOPARLAYACAK VAKTİMİZ OLMAMASINI HOŞ GÖRÜRSÜNÜZ. BURAYA TEMİZLİK EKİBİ GETİRMEK OLDUKÇA ZOR, ANLARSINIZ. İNANIN BANA, BU ZİYARETİNİZİ HİÇBİR ŞEKİLDE KİŞİSEL ALGILAMIYORUM.",
["Merhaba dostum."] = "MERHABA DOSTUM.",
["Merhaba yeni dostlarım!"] = "MERHABA YENİ DOSTLARIM!",
["Merhaba! Evet, sizin için ne yapabilirim?"] = "MERHABA! EVET, SİZİN İÇİN NE YAPABİLİRİM?",
["Merhaba, First World Bank. Elbette ilk çocuğunuzu üniversiteye göndermek için kredi ayarlayabiliriz. Sonuçta onlar bize ait."] = "MERHABA, FIRST WORLD BANK. ELBETTE İLK ÇOCUĞUNUZU ÜNİVERSİTEYE GÖNDERMEK İÇİN KREDİ AYARLAYABİLİRİZ. SONUÇTA ONLAR BİZE AİT.",
["Merhaba, First World Bank. Elbette! Güncel hisse değeri... neden bir saat sonra tekrar aramıyorsunuz?"] = "MERHABA, FIRST WORLD BANK. ELBETTE! GÜNCEL HİSSE DEĞERİ... NEDEN BİR SAAT SONRA TEKRAR ARAMIYORSUNUZ?",
["Merhaba, First World Bank. Hayır efendim, teklifinize teşekkürler ama küçük yazılara bakarsanız sizi bizim siktiğimizi görürsünüz. Hem de sert!"] = "MERHABA, FIRST WORLD BANK. HAYIR EFENDİM, TEKLİFİNİZE TEŞEKKÜRLER AMA KÜÇÜK YAZILARA BAKARSANIZ SİZİ BİZİM SİKTİĞİMİZİ GÖRÜRSÜNÜZ. HEM DE SERT!",
["Merhaba, Reilly-Needazheet'e ulaşmaya çalışıyorum. Adının baş harfi 'I'."] = "MERHABA, REİLLY-NEEDAZHEET'E ULAŞMAYA ÇALIŞIYORUM. ADININ BAŞ HARFİ 'I'.",
["Merhaba, ben GenSec'ten Hilary. Barney orada mı?"] = "MERHABA, BEN GENSEC'TEN HİLARY. BARNEY ORADA MI?",
["Merhaba, ben Jen. GenSec'ten arıyorum. Zaman kilidinizde plan dışı bir etkinleştirme tespit ettik. Her şeyin yolunda olduğundan emin olmak için aradım."] = "MERHABA, BEN JEN. GENSEC'TEN ARIYORUM. ZAMAN KİLİDİNİZDE PLAN DIŞI BİR ETKİNLEŞTİRME TESPİT ETTİK. HER ŞEYİN YOLUNDA OLDUĞUNDAN EMİN OLMAK İÇİN ARADIM.",
["Merhaba, ben Özel Ajan, şey, Smith. Panik odasının kodunu söyleyebilir misiniz? Terminallerimiz çalışmıyor. Bugünkü kodu alamıyoruz."] = "MERHABA, BEN ÖZEL AJAN, ŞEY, SMİTH. PANİK ODASININ KODUNU SÖYLEYEBİLİR MİSİNİZ? TERMİNALLERİMİZ ÇALIŞMIYOR. BUGÜNKÜ KODU ALAMIYORUZ.",
["Merhaba, bilgisayardaki hesabımla sorun yaşıyorum. İnternet mi yapmalıyım?"] = "MERHABA, BİLGİSAYARDAKİ HESABIMLA SORUN YAŞIYORUM. İNTERNET Mİ YAPMALIYIM?",
["Merhaba, bu da ne...?"] = "MERHABA, BU DA NE...?",
