["Merhaba."] = "MERHABA.",
["Merhaba. Az önce bir program izledim, banka soyulmuş. Ben de paramı soyulmayan bir bankaya taşımak istiyorum."] = "MERHABA. AZ ÖNCE BİR PROGRAM İZLEDİM, BANKA SOYULMUŞ. BEN DE PARAMI SOYULMAYAN BİR BANKAYA TAŞIMAK İSTİYORUM.",
["Merhaba. Az önce bir program izledim, banka soyulmuş. Paramı soyulmayan bir bankaya taşımak istiyorum."] = "MERHABA. AZ ÖNCE BİR PROGRAM İZLEDİM, BANKA SOYULMUŞ. PARAMI SOYULMAYAN BİR BANKAYA TAŞIMAK İSTİYORUM.",
["Merhaba. Benim adım Locke. Murkywater'ın kurduğu siber görev gücünün başındayım. Çıkarlarımıza yaptığınız onca saldırı yüzünden Crime.net'inize sızıp sizi yok etmekle görevlendirildik. Kuşkusuz anladığınız üzere sızma kısmı tamamlandı. Ancak bu düğmeye basarak sizi bitirmek yerine bir teklifle geldim. Benimle çalışmaya ne dersiniz? Size Murkywater hakkında istihbarat, fırsatlar ve malzeme sağlayabilirim. Üstelik sizi iş arkadaşlarımın dikkatinden uzak tutabilirim. Ne... dersiniz?"] = "MERHABA. BENİM ADIM LOCKE. MURKYWATER'IN KURDUĞU SİBER GÖREV GÜCÜNÜN BAŞINDAYIM. ÇIKARLARIMIZA YAPTIĞINIZ ONCA SALDIRI YÜZÜNDEN CRIME.NET'İNİZE SIZIP SİZİ YOK ETMEKLE GÖREVLENDİRİLDİK. KUŞKUSUZ ANLADIĞINIZ ÜZERE SIZMA KISMI TAMAMLANDI. ANCAK BU DÜĞMEYE BASARAK SİZİ BİTİRMEK YERİNE BİR TEKLİFLE GELDİM. BENİMLE ÇALIŞMAYA NE DERSİNİZ? SİZE MURKYWATER HAKKINDA İSTİHBARAT, FIRSATLAR VE MALZEME SAĞLAYABİLİRİM. ÜSTELİK SİZİ İŞ ARKADAŞLARIMIN DİKKATİNDEN UZAK TUTABİLİRİM. NE... DERSİNİZ?",
