["Millet. Kaçmaya hazır olduğunuzda o diyafona cevap verin. Geride bıraktığınız her şey orada kalır."] = "MİLLET. KAÇMAYA HAZIR OLDUĞUNUZDA O DİYAFONA CEVAP VERİN. GERİDE BIRAKTIĞINIZ HER ŞEY ORADA KALIR.",
["Millet. Vinci kullanın. Yerine getirin."] = "MİLLET. VİNCİ KULLANIN. YERİNE GETİRİN.",
["Millet..."] = "MİLLET...",
["Millet... Doğru olanın nasıl göründüğüne dair ipucu görüyor musunuz?"] = "MİLLET... DOĞRU OLANIN NASIL GÖRÜNDÜĞÜNE DAİR İPUCU GÖRÜYOR MUSUNUZ?",
