["Motosiklet"] = "MOTOSİKLET",
["Motosiklet Parçası"] = "MOTOSİKLET PARÇASI",
["Motosiklet sürerken bunları takıp karşıdan gelen eşekarılarının ödünü kopar."] = "MOTOSİKLET SÜRERKEN BUNLARI TAKIP KARŞIDAN GELEN EŞEKARILARININ ÖDÜNÜ KOPAR.",
["Motosikleti bozulmuştu. Issızlığın ortasında kalmanın tam zamanıydı. Sığınaktaki Noel partisini kesin kaçıracaktı. Bu yıl Rust’a Jiro’nun sake yumurtalı kokteylinden yoktu. Kahretsin. Çantasını alıp yürümeye başladı. Güneş karlı manzaranın üzerinde batıyordu. Döküntü bir çiftlik evinin yanından geçerken içeriden yürek burkan bir çığlık geldi. Rust duraksadı. Onun işi değildi. Ama bir şey fikrini değiştirdi. Pencereden yerde birini görüp içeri koştu; ağacını süslerken düşmüş yaşlı bir kadın buldu. Kalkmasına yardım edip yaralarıyla ilgilendikten sonra çaya kaldı. Meğer ahırda hâlâ çalışan klasik bir motosiklet varmış, ödünç alabilirmiş. Belki o partiyi kaçırmayacaktı..."] = "MOTOSİKLETİ BOZULMUŞTU. ISSIZLIĞIN ORTASINDA KALMANIN TAM ZAMANIYDI. SIĞINAKTAKİ NOEL PARTİSİNİ KESİN KAÇIRACAKTI. BU YIL RUST’A JIRO’NUN SAKE YUMURTALI KOKTEYLİNDEN YOKTU. KAHRETSİN. ÇANTASINI ALIP YÜRÜMEYE BAŞLADI. GÜNEŞ KARLI MANZARANIN ÜZERİNDE BATIYORDU. DÖKÜNTÜ BİR ÇİFTLİK EVİNİN YANINDAN GEÇERKEN İÇERİDEN YÜREK BURKAN BİR ÇIĞLIK GELDİ. RUST DURAKSADI. ONUN İŞİ DEĞİLDİ. AMA BİR ŞEY FİKRİNİ DEĞİŞTİRDİ. PENCEREDEN YERDE BİRİNİ GÖRÜP İÇERİ KOŞTU; AĞACINI SÜSLERKEN DÜŞMÜŞ YAŞLI BİR KADIN BULDU. KALKMASINA YARDIM EDİP YARALARIYLA İLGİLENDİKTEN SONRA ÇAYA KALDI. MEĞER AHIRDA HÂLÂ ÇALIŞAN KLASİK BİR MOTOSİKLET VARMIŞ, ÖDÜNÇ ALABİLİRMİŞ. BELKİ O PARTİYİ KAÇIRMAYACAKTI...",
["Motosikleti toplamaya başlayabilmesi için tamirciye kamyonuna kadar eşlik et"] = "MOTOSİKLETİ TOPLAMAYA BAŞLAYABİLMESİ İÇİN TAMİRCİYE KAMYONUNA KADAR EŞLİK ET",
["Motosikletini tamir edebilirsin ama kendini edemezsin. Ne olmuş? Sen tamircisin, lanet bir psikiyatrist değil."] = "MOTOSİKLETİNİ TAMİR EDEBİLİRSİN AMA KENDİNİ EDEMEZSİN. NE OLMUŞ? SEN TAMİRCİSİN, LANET BİR PSİKİYATRİST DEĞİL.",
["Motosikletçilerin kapı patlayıcılarını nerede sakladığını bul."] = "MOTOSİKLETÇİLERİN KAPI PATLAYICILARINI NEREDE SAKLADIĞINI BUL.",
