["Muhteşem dostlarım. Teşekkürler. Bu işlerde Vlad'a yardım ettiğiniz için teşekkürler. Coyopa'lar çok kızacak ama sikimde değil. Önemli değil. Onlarla ilgilenme vakti sonra gelecek. Yakında size ulaşacağım. Oralarda yapacağınız daha çok iş var."] = "MUHTEŞEM DOSTLARIM. TEŞEKKÜRLER. BU İŞLERDE VLAD'A YARDIM ETTİĞİNİZ İÇİN TEŞEKKÜRLER. COYOPA'LAR ÇOK KIZACAK AMA SİKİMDE DEĞİL. ÖNEMLİ DEĞİL. ONLARLA İLGİLENME VAKTİ SONRA GELECEK. YAKINDA SİZE ULAŞACAĞIM. ORALARDA YAPACAĞINIZ DAHA ÇOK İŞ VAR.",
["Muhteşem dostlarım. Şimdi sizi oradan çıkarabilmem için girişe dönmelisiniz."] = "MUHTEŞEM DOSTLARIM. ŞİMDİ SİZİ ORADAN ÇIKARABİLMEM İÇİN GİRİŞE DÖNMELİSİNİZ.",
["Muhteşem ekip. Kapı açılıyor. Artık sadece o lazerleri devre dışı bırakmalısınız."] = "MUHTEŞEM EKİP. KAPI AÇILIYOR. ARTIK SADECE O LAZERLERİ DEVRE DIŞI BIRAKMALISINIZ.",
["Muhteşem iş! Bu güzel arabalar bir hafta içinde Arap şeyhlerinin elinde olacak. İyi iş!"] = "MUHTEŞEM İŞ! BU GÜZEL ARABALAR BİR HAFTA İÇİNDE ARAP ŞEYHLERİNİN ELİNDE OLACAK. İYİ İŞ!",
["Muhteşem yaptınız. Sessiz ve etkili. Mükemmel iş."] = "MUHTEŞEM YAPTINIZ. SESSİZ VE ETKİLİ. MÜKEMMEL İŞ.",
["Muhteşem! 25 milyonluk işlemi onayladım."] = "MUHTEŞEM! 25 MİLYONLUK İŞLEMİ ONAYLADIM.",
["Muhteşem! Ama kaybedecek vakit yok. Çalıştırıp o ağaçları devirmeye başlayın."] = "MUHTEŞEM! AMA KAYBEDECEK VAKİT YOK. ÇALIŞTIRIP O AĞAÇLARI DEVİRMEYE BAŞLAYIN.",
["Muhteşem! Ateş sönüyor."] = "MUHTEŞEM! ATEŞ SÖNÜYOR.",
["Muhteşem! Bahse girerim o güzellik anakaradan görünüyordur. Çıkalım dostlar. Gidecek yerlerimiz, çalacak şeylerimiz var."] = "MUHTEŞEM! BAHSE GİRERİM O GÜZELLİK ANAKARADAN GÖRÜNÜYORDUR. ÇIKALIM DOSTLAR. GİDECEK YERLERİMİZ, ÇALACAK ŞEYLERİMİZ VAR.",
["Muhteşem! Bize fazladan para, içkiler benden!"] = "MUHTEŞEM! BİZE FAZLADAN PARA, İÇKİLER BENDEN!",
["Muhteşem! Bütün keçiler tamam! Şimdi yola çıkma vakti ekip!"] = "MUHTEŞEM! BÜTÜN KEÇİLER TAMAM! ŞİMDİ YOLA ÇIKMA VAKTİ EKİP!",
["Muhteşem! Doğru sanat eserini aldık. Şimdi teslimat alanındaki kamyona koyun."] = "MUHTEŞEM! DOĞRU SANAT ESERİNİ ALDIK. ŞİMDİ TESLİMAT ALANINDAKİ KAMYONA KOYUN.",
["Muhteşem! Doğu kıyılarını ateşe vermeden kurtulduğunuza sevindim."] = "MUHTEŞEM! DOĞU KIYILARINI ATEŞE VERMEDEN KURTULDUĞUNUZA SEVİNDİM.",
["Muhteşem! Hepsini etkisiz hâle getirdiniz. Parayı alın."] = "MUHTEŞEM! HEPSİNİ ETKİSİZ HÂLE GETİRDİNİZ. PARAYI ALIN.",
["Muhteşem! Her şey kusursuz ilerliyor. Şimdi lütfen herkes hava kilidine girsin."] = "MUHTEŞEM! HER ŞEY KUSURSUZ İLERLİYOR. ŞİMDİ LÜTFEN HERKES HAVA KİLİDİNE GİRSİN.",
