["Nasıl hareket edeceğinizi planlamak için fırsatınız bu."] = "NASIL HAREKET EDECEĞİNİZİ PLANLAMAK İÇİN FIRSATINIZ BU.",
["Nasıl isterseniz."] = "NASIL İSTERSENİZ.",
["Nasıl işlediğini biliyorsunuz. Güvenliğe gözünüz açık olsun. Sivilleri kontrol altında tutmalısınız. Anahtar kartları da hep işe yarar."] = "NASIL İŞLEDİĞİNİ BİLİYORSUNUZ. GÜVENLİĞE GÖZÜNÜZ AÇIK OLSUN. SİVİLLERİ KONTROL ALTINDA TUTMALISINIZ. ANAHTAR KARTLARI DA HEP İŞE YARAR.",
["Nasıl kazanacağınızı biliyorsunuz. Kazanın o zaman."] = "NASIL KAZANACAĞINIZI BİLİYORSUNUZ. KAZANIN O ZAMAN.",
["Nasıl olduğunu biliyorsun. Bir kez söyle, iki kez söyle; üçüncüde olur. Ve unutma... çalmasını istediğin her şeyi çalar, hacklemesini istediğin her şeyi hackler. Adını söyle; seni gözaltından takasla çıkarır. Bain! Bain! B..."] = "NASIL OLDUĞUNU BİLİYORSUN. BİR KEZ SÖYLE, İKİ KEZ SÖYLE; ÜÇÜNCÜDE OLUR. VE UNUTMA... ÇALMASINI İSTEDİĞİN HER ŞEYİ ÇALAR, HACKLEMESİNİ İSTEDİĞİN HER ŞEYİ HACKLER. ADINI SÖYLE; SENİ GÖZALTINDAN TAKASLA ÇIKARIR. BAIN! BAIN! B...",
["Nasıl olduğunu merak edecekler ama kimin yaptığını bilecekler. Benimle uğraşmamayı da öğrenecekler."] = "NASIL OLDUĞUNU MERAK EDECEKLER AMA KİMİN YAPTIĞINI BİLECEKLER. BENİMLE UĞRAŞMAMAYI DA ÖĞRENECEKLER.",
["Nasıl olduğunu çözemiyorum..."] = "NASIL OLDUĞUNU ÇÖZEMİYORUM...",
["Nasıl olursa olsun ana kapıyı geçin."] = "NASIL OLURSA OLSUN ANA KAPIYI GEÇİN.",
["Nasıl olursa olsun eve girin. Bu saatten sonra gizlenmeye gerek yok."] = "NASIL OLURSA OLSUN EVE GİRİN. BU SAATTEN SONRA GİZLENMEYE GEREK YOK.",
["Nasıl savaşabildiğinizi biliyorum, öyle savaşın!"] = "NASIL SAVAŞABİLDİĞİNİZİ BİLİYORUM, ÖYLE SAVAŞIN!",
["Nasıl yürütmek isterseniz öyle yürütün. Gösteri sizin, ben hattayım. Bol şans."] = "NASIL YÜRÜTMEK İSTERSENİZ ÖYLE YÜRÜTÜN. GÖSTERİ SİZİN, BEN HATTAYIM. BOL ŞANS.",
["Nasıl çalıştıklarını görmen için küçük bir deneme hazırladım."] = "NASIL ÇALIŞTIKLARINI GÖRMEN İÇİN KÜÇÜK BİR DENEME HAZIRLADIM.",
["Nasıl... Şey... Bir şey düşünmeliyim... Nasıl gireriz..."] = "NASIL... ŞEY... BİR ŞEY DÜŞÜNMELİYİM... NASIL GİRERİZ...",
["Nathan Garnet'a ait Garnet Group Building'in 22. katında, milyonlar değerinde elmasların bulunduğu bir Kasa var. Binanın güvenlik sistemi ileri teknoloji, güvenlikçileri de tetiğe basmaya hevesli. Neyse ki devam eden bir doğum günü partisi dikkatlerini dağıtıyor. "] = "NATHAN GARNET'A AİT GARNET GROUP BUİLDİNG'İN 22. KATINDA, MİLYONLAR DEĞERİNDE ELMASLARIN BULUNDUĞU BİR KASA VAR. BİNANIN GÜVENLİK SİSTEMİ İLERİ TEKNOLOJİ, GÜVENLİKÇİLERİ DE TETİĞE BASMAYA HEVESLİ. NEYSE Kİ DEVAM EDEN BİR DOĞUM GÜNÜ PARTİSİ DİKKATLERİNİ DAĞITIYOR. ",
