["Ne var?"] = "NE VAR?",
["Ne yakıyorlar? Muhtemelen bize lazımdı!"] = "NE YAKIYORLAR? MUHTEMELEN BİZE LAZIMDI!",
["Ne yapabileceğime bir bakayım."] = "NE YAPABİLECEĞİME BİR BAKAYIM.",
["Ne yapacağınızı biliyorsunuz millet. Dışarı çıkın, kafes parçalarını alıp birleştirin."] = "NE YAPACAĞINIZI BİLİYORSUNUZ MİLLET. DIŞARI ÇIKIN, KAFES PARÇALARINI ALIP BİRLEŞTİRİN.",
["Ne yapacağınızı biliyorsunuz!"] = "NE YAPACAĞINIZI BİLİYORSUNUZ!",
["Ne yapacağınızı biliyorsunuz. C4'ü kurun, gerisini o halletsin."] = "NE YAPACAĞINIZI BİLİYORSUNUZ. C4'Ü KURUN, GERİSİNİ O HALLETSİN.",
["Ne yapacağınızı biliyorsunuz. Dışarı çıkın. Kafesi kurun!"] = "NE YAPACAĞINIZI BİLİYORSUNUZ. DIŞARI ÇIKIN. KAFESİ KURUN!",
["Ne yapacağınızı biliyorsunuz. Halledin. "] = "NE YAPACAĞINIZI BİLİYORSUNUZ. HALLEDİN. ",
["Ne yapacağınızı biliyorsunuz. Helikoptere işaret verin, daha fazla malzeme bırakalım. Ya da kaçın. Karar sizin."] = "NE YAPACAĞINIZI BİLİYORSUNUZ. HELİKOPTERE İŞARET VERİN, DAHA FAZLA MALZEME BIRAKALIM. YA DA KAÇIN. KARAR SİZİN.",
["Ne yapacağınızı biliyorsunuz. Muhafızlara ve kameralara dikkat edin. Sivilleri kontrol altında tutun. Etrafta Anahtar Kartları, banka müdürü, yardımcı olabilecek ne varsa arayın."] = "NE YAPACAĞINIZI BİLİYORSUNUZ. MUHAFIZLARA VE KAMERALARA DİKKAT EDİN. SİVİLLERİ KONTROL ALTINDA TUTUN. ETRAFTA ANAHTAR KARTLARI, BANKA MÜDÜRÜ, YARDIMCI OLABİLECEK NE VARSA ARAYIN.",
["Ne yapacağınızı biliyorsunuz. Vagonlara girip o kalıpları alın."] = "NE YAPACAĞINIZI BİLİYORSUNUZ. VAGONLARA GİRİP O KALIPLARI ALIN.",
["Ne yaparsanız yapın, o orospu çocuklarının elektriği kesmesine izin vermeyin!"] = "NE YAPARSANIZ YAPIN, O OROSPU ÇOCUKLARININ ELEKTRİĞİ KESMESİNE İZİN VERMEYİN!",
["Ne yapmanız gerekiyorsa yapın ama işi bitirin."] = "NE YAPMANIZ GEREKİYORSA YAPIN AMA İŞİ BİTİRİN.",
["Ne yapmanız gerektiği umurumda değil. Vurun sikikleri."] = "NE YAPMANIZ GEREKTİĞİ UMURUMDA DEĞİL. VURUN SİKİKLERİ.",
["Ne yapmanız gerektiğini açıklamama gerek olmadığına eminim."] = "NE YAPMANIZ GEREKTİĞİNİ AÇIKLAMAMA GEREK OLMADIĞINA EMİNİM.",
["Ne yapmaya çalışıyorsunuz?"] = "NE YAPMAYA ÇALIŞIYORSUNUZ?",
["Ne yaptıklarını ve kime yaptıklarını bilmiyor olabilirlerdi ama bunun önemi yok. Hak ettiklerini, hatta fazlasını aldılar. John geri döndü."] = "NE YAPTIKLARINI VE KİME YAPTIKLARINI BİLMİYOR OLABİLİRLERDİ AMA BUNUN ÖNEMİ YOK. HAK ETTİKLERİNİ, HATTA FAZLASINI ALDILAR. JOHN GERİ DÖNDÜ.",
["Ne yaptınız lan millet! Onları şimdi öldürmeyecektiniz! Wick derslerini vermek için canlı istiyordu... Umarım öldüklerini bilmekle yetinir."] = "NE YAPTINIZ LAN MİLLET! ONLARI ŞİMDİ ÖLDÜRMEYECEKTİNİZ! WICK DERSLERİNİ VERMEK İÇİN CANLI İSTİYORDU... UMARIM ÖLDÜKLERİNİ BİLMEKLE YETİNİR.",
["Ne yaptığını anlamıyorum. O kameradan kurtulmalısın. Dediğimi yapıp ECM Karıştırıcı'yı yerleştir."] = "NE YAPTIĞINI ANLAMIYORUM. O KAMERADAN KURTULMALISIN. DEDİĞİMİ YAPIP ECM KARIŞTIRICI'YI YERLEŞTİR.",
["Ne yaptığını sanıyorsun lan dostum!?"] = "NE YAPTIĞINI SANIYORSUN LAN DOSTUM!?",
["Ne yaptığını sanıyorsun lan!?"] = "NE YAPTIĞINI SANIYORSUN LAN!?",
["Ne yaptığını sanıyorsun lan?"] = "NE YAPTIĞINI SANIYORSUN LAN?",
["Ne yapıyorsanız devam edin."] = "NE YAPIYORSANIZ DEVAM EDİN.",
["Ne yapıyorsun Dallas? Ben söylemeden ECM'yi kullanma demiştim!"] = "NE YAPIYORSUN DALLAS? BEN SÖYLEMEDEN ECM'Yİ KULLANMA DEMİŞTİM!",
["Ne yapıyorsun Vlad?"] = "NE YAPIYORSUN VLAD?",
["Ne yapıyorsun hödük?"] = "NE YAPIYORSUN HÖDÜK?",
["Ne yapıyorsunuz lan?"] = "NE YAPIYORSUNUZ LAN?",
["Ne yapıyorsunuz!? İçeri bile giremediniz. B planına geçelim. Bir dahaki sefere göze batmayın."] = "NE YAPIYORSUNUZ!? İÇERİ BİLE GİREMEDİNİZ. B PLANINA GEÇELİM. BİR DAHAKİ SEFERE GÖZE BATMAYIN.",
["Ne yapıyorsunuz, içeri girin!"] = "NE YAPIYORSUNUZ, İÇERİ GİRİN!",
["Ne yapıyorsunuz, ortalığı kurşunluyorsunuz! Şimdi her yeri kilitleyecekler!"] = "NE YAPIYORSUNUZ, ORTALIĞI KURŞUNLUYORSUNUZ! ŞİMDİ HER YERİ KİLİTLEYECEKLER!",
["Ne yapıyorsunuz?"] = "NE YAPIYORSUNUZ?",
["Ne yapıyorsunuz? Bain'i takip edin!"] = "NE YAPIYORSUNUZ? BAIN'İ TAKİP EDİN!",
["Ne yapıyorsunuz? Eseri güvene alın!"] = "NE YAPIYORSUNUZ? ESERİ GÜVENE ALIN!",
["Ne yapıyorsunuz? Garrett'ın ofisini aramalısınız."] = "NE YAPIYORSUNUZ? GARRETT'IN OFİSİNİ ARAMALISINIZ.",
["Ne yapıyorsunuz? Kalabalık böyle kontrol edilmez!"] = "NE YAPIYORSUNUZ? KALABALIK BÖYLE KONTROL EDİLMEZ!",
["Ne yapıyorsunuz? Kıpırdayın!"] = "NE YAPIYORSUNUZ? KIPIRDAYIN!",
["Ne yapıyorsunuz? Nazik davranın!"] = "NE YAPIYORSUNUZ? NAZİK DAVRANIN!",
["Ne yapıyorsunuz? O kamera çalıştığı sürece fark edilmeden giremezsiniz."] = "NE YAPIYORSUNUZ? O KAMERA ÇALIŞTIĞI SÜRECE FARK EDİLMEDEN GİREMEZSİNİZ.",
["Ne yapıyorsunuz? Vlad'ın bağlarını çözmesine yardım edin!"] = "NE YAPIYORSUNUZ? VLAD'IN BAĞLARINI ÇÖZMESİNE YARDIM EDİN!",
["Ne yapıyorsunuz? İşaretlememi bekleyin. Doğru kabloyu kesmeliyiz."] = "NE YAPIYORSUNUZ? İŞARETLEMEMİ BEKLEYİN. DOĞRU KABLOYU KESMELİYİZ.",
["Ne yapıyorsunuz?! Herkese burada olduğunuzu duyurdunuz."] = "NE YAPIYORSUNUZ?! HERKESE BURADA OLDUĞUNUZU DUYURDUNUZ.",
["Ne yapıyorsunuz?! Çıkın oradan!"] = "NE YAPIYORSUNUZ?! ÇIKIN ORADAN!",
["Ne yazık ki 'Osuruk Krakerleri' gibi bir şeyi üretip pazarlama planınızda ciddi olduğunuzdan şüpheliyim."] = "NE YAZIK Kİ 'OSURUK KRAKERLERİ' GİBİ BİR ŞEYİ ÜRETİP PAZARLAMA PLANINIZDA CİDDİ OLDUĞUNUZDAN ŞÜPHELİYİM.",
["Ne yazık ki bazen mühimmat kıtlığı yaşanabilir. Bu yüzden düşmanı etkili biçimde indirebilmek önemlidir."] = "NE YAZIK Kİ BAZEN MÜHİMMAT KITLIĞI YAŞANABİLİR. BU YÜZDEN DÜŞMANI ETKİLİ BİÇİMDE İNDİREBİLMEK ÖNEMLİDİR.",
["Ne yazık ki kredi limitinizi 'fahişeler ve kokain' gibi ek masrafları karşılamak için artıramayız."] = "NE YAZIK Kİ KREDİ LİMİTİNİZİ 'FAHİŞELER VE KOKAİN' GİBİ EK MASRAFLARI KARŞILAMAK İÇİN ARTIRAMAYIZ.",
["Ne zaman başlamak isterseniz maskeleri takın."] = "NE ZAMAN BAŞLAMAK İSTERSENİZ MASKELERİ TAKIN.",
["Ne zaman bırakmamak gerektiğini bilmek, ne zaman havlu atacağını bilmekten zordur. Kibir veya aptalca gurur seni yoldan çıkarmasın. Bazen bir soruna öyle kapılırsın ki asıl sorunun ne olduğunu göremezsin. Bu, herkesin başını büyük belaya sokar. Çok kötü belaya. O yüzden doğru olanı yap, yanlış yola sapmazsın."] = "NE ZAMAN BIRAKMAMAK GEREKTİĞİNİ BİLMEK, NE ZAMAN HAVLU ATACAĞINI BİLMEKTEN ZORDUR. KİBİR VEYA APTALCA GURUR SENİ YOLDAN ÇIKARMASIN. BAZEN BİR SORUNA ÖYLE KAPILIRSIN Kİ ASIL SORUNUN NE OLDUĞUNU GÖREMEZSİN. BU, HERKESİN BAŞINI BÜYÜK BELAYA SOKAR. ÇOK KÖTÜ BELAYA. O YÜZDEN DOĞRU OLANI YAP, YANLIŞ YOLA SAPMAZSIN.",
["Ne zaman hazır olursanız hazırım."] = "NE ZAMAN HAZIR OLURSANIZ HAZIRIM.",
["Ne zaman iş yapmaya kalksak Buluc, üyesi olduğu şu deli Maya tarikatından, ruhunu kurban etmekten söz ederdi. Vlad'ın tek dini para, kadınlar ve Sputnik içmek!"] = "NE ZAMAN İŞ YAPMAYA KALKSAK BULUC, ÜYESİ OLDUĞU ŞU DELİ MAYA TARİKATINDAN, RUHUNU KURBAN ETMEKTEN SÖZ EDERDİ. VLAD'IN TEK DİNİ PARA, KADINLAR VE SPUTNİK İÇMEK!",
["Ne Çok Seçenek Var"] = "NE ÇOK SEÇENEK VAR",
["Ne çaldınız lan siz!?"] = "NE ÇALDINIZ LAN SİZ!?",
["Ne çaldınız siz amına koyayım!?"] = "NE ÇALDINIZ SİZ AMINA KOYAYIM!?",
["Ne çarpışmaydı ama. Polisler size mola vermeyecek, ayağa kalkın!"] = "NE ÇARPIŞMAYDI AMA. POLİSLER SİZE MOLA VERMEYECEK, AYAĞA KALKIN!",
["Ne çevirmeye çalışıyorsunuz!?"] = "NE ÇEVİRMEYE ÇALIŞIYORSUNUZ!?",
["Ne İşe Yarar?"] = "NE İŞE YARAR?",
["Ne şoförü? Ne diyorsun, sadece biraz tavsiye veriyorum."] = "NE ŞOFÖRÜ? NE DİYORSUN, SADECE BİRAZ TAVSİYE VERİYORUM.",
["Ne! Alışverişçi bir pislik kokainimle dolaşıyor! Bulun!"] = "NE! ALIŞVERİŞÇİ BİR PİSLİK KOKAİNİMLE DOLAŞIYOR! BULUN!",
["Ne! Beni rahat bırakın!"] = "NE! BENİ RAHAT BIRAKIN!",
["Ne!? Lastiklerimize ateş ediyorlar!"] = "NE!? LASTİKLERİMİZE ATEŞ EDİYORLAR!",
["Ne!? Mendoza karteli hâlâ orada! Halledin onları!"] = "NE!? MENDOZA KARTELİ HÂLÂ ORADA! HALLEDİN ONLARI!",
["Ne!? O Kataru'nun peşinde olduğu şey bu mu? Çabuk, alın ve hemen çıkın oradan."] = "NE!? O KATARU'NUN PEŞİNDE OLDUĞU ŞEY BU MU? ÇABUK, ALIN VE HEMEN ÇIKIN ORADAN.",
["Ne!? Sunucuyu koşarak çıkarın, millet. Yetiştirebilirsiniz!"] = "NE!? SUNUCUYU KOŞARAK ÇIKARIN, MİLLET. YETİŞTİREBİLİRSİNİZ!",
["Ne, akıl mı okuyorsunuz? Evet, o evrak çantasını istiyorum. Nereden bildiniz?"] = "NE, AKIL MI OKUYORSUNUZ? EVET, O EVRAK ÇANTASINI İSTİYORUM. NEREDEN BİLDİNİZ?",
["Ne, ciddi misin?"] = "NE, CİDDİ MİSİN?",
["Ne, hâlâ o şifreyi mi arıyorsunuz?"] = "NE, HÂLÂ O ŞİFREYİ Mİ ARIYORSUNUZ?",
["Ne, kayınbiraderimi mi tanıyor?"] = "NE, KAYINBİRADERİMİ Mİ TANIYOR?",
["Ne, kayınbiraderimi tanıyor mu?"] = "NE, KAYINBİRADERİMİ TANIYOR MU?",
["Ne, köşedeki örümceklerden mi korkuyorsunuz? O kodu daha iyi arayın dostlar!"] = "NE, KÖŞEDEKİ ÖRÜMCEKLERDEN Mİ KORKUYORSUNUZ? O KODU DAHA İYİ ARAYIN DOSTLAR!",
["Ne, yakın temas mı arıyorsun amına koyayım?"] = "NE, YAKIN TEMAS MI ARIYORSUN AMINA KOYAYIM?",
["Ne... Bir tane daha mı? Millet, başka şalter kutusu var. Onun da bağlantılarını değiştirin."] = "NE... BİR TANE DAHA MI? MİLLET, BAŞKA ŞALTER KUTUSU VAR. ONUN DA BAĞLANTILARINI DEĞİŞTİRİN.",
["Ne... Elephant'ın elindeki bu muydu? Bu... Yok, tam değil, ha? Alıp çıkın oradan."] = "NE... ELEPHANT'IN ELİNDEKİ BU MUYDU? BU... YOK, TAM DEĞİL, HA? ALIP ÇIKIN ORADAN.",
["Ne... Hey! Benimle oyun oynama!"] = "NE... HEY! BENİMLE OYUN OYNAMA!",
["Ne... Matt Roscoe bu! Tabii o gelinciğin de işin içinde olması gerekiyordu! Belki hemen şurada öldürmelisiniz!"] = "NE... MATT ROSCOE BU! TABİİ O GELİNCİĞİN DE İŞİN İÇİNDE OLMASI GEREKİYORDU! BELKİ HEMEN ŞURADA ÖLDÜRMELİSİNİZ!",
["Ne... Millet, bilgisayarı koruyun!"] = "NE... MİLLET, BİLGİSAYARI KORUYUN!",
["Ne... Polis telsizi tarayıcımdır o. Polislerin yakında olduğu yok. "] = "NE... POLİS TELSİZİ TARAYICIMDIR O. POLİSLERİN YAKINDA OLDUĞU YOK. ",
["Ne... The Diamond'ı zemine indirdiler. Tamam, geçmenin yolunu açmalıyız! Oraya bir matkap kurun."] = "NE... THE DIAMOND'I ZEMİNE İNDİRDİLER. TAMAM, GEÇMENİN YOLUNU AÇMALIYIZ! ORAYA BİR MATKAP KURUN.",
["Ne... bu Matt Roscoe! Tabii o gelincik de işin içinde olacaktı! Belki de onu burada, hemen öldürmelisiniz!"] = "NE... BU MATT ROSCOE! TABİİ O GELİNCİK DE İŞİN İÇİNDE OLACAKTI! BELKİ DE ONU BURADA, HEMEN ÖLDÜRMELİSİNİZ!",
["Ne... hey! Beni çıkarmanız için Vlad mı gönderdi?"] = "NE... HEY! BENİ ÇIKARMANIZ İÇİN VLAD MI GÖNDERDİ?",
["Ne? Biz hiçbir şey döşemedik ki. Bu nasıl mümkün olabilir?"] = "NE? BİZ HİÇBİR ŞEY DÖŞEMEDİK Kİ. BU NASIL MÜMKÜN OLABİLİR?",
["Ne? Dans Etmemi mi İstiyorsun?"] = "NE? DANS ETMEMİ Mİ İSTİYORSUN?",
["Ne? Hadi ama! Ben gidiyorum!"] = "NE? HADİ AMA! BEN GİDİYORUM!",
["Ne? Hayır! Bütün Tin Boy'ları satmışlar!"] = "NE? HAYIR! BÜTÜN TİN BOY'LARI SATMIŞLAR!",
["Ne? Hiç ceza almadan kurtulmak istemiyor musunuz? Ben istiyorum, o yüzden lütfen acele edip bütün o af belgelerini alın!"] = "NE? HİÇ CEZA ALMADAN KURTULMAK İSTEMİYOR MUSUNUZ? BEN İSTİYORUM, O YÜZDEN LÜTFEN ACELE EDİP BÜTÜN O AF BELGELERİNİ ALIN!",
["Ne? Kimsiniz?"] = "NE? KİMSİNİZ?",
["Ne? Polis kılığına mı girmemi istiyorsunuz??"] = "NE? POLİS KILIĞINA MI GİRMEMİ İSTİYORSUNUZ??",
["Ne? Soru işaretlerinde durdu. Bu her şey olabilir."] = "NE? SORU İŞARETLERİNDE DURDU. BU HER ŞEY OLABİLİR.",
["Ne? Vinç durmuş, yeniden çalıştırın!"] = "NE? VİNÇ DURMUŞ, YENİDEN ÇALIŞTIRIN!",
["Ne? Vlad mı? Seni pis Rus! Kayınbiraderin nasıl? Hani... neydi adı... Hootiejudy... Houdini?"] = "NE? VLAD MI? SENİ PİS RUS! KAYINBİRADERİN NASIL? HANİ... NEYDİ ADI... HOOTİEJUDY... HOUDİNİ?",
["Ne? Yanlış karo olmalı!"] = "NE? YANLIŞ KARO OLMALI!",
["Ne?!"] = "NE?!",
["Ne?! Zaman kilidi durdu. Hmm, ECM Karıştırıcınız onu bozuyor olabilir. O karıştırıcıları bir süre kullanmasanız iyi olur."] = "NE?! ZAMAN KİLİDİ DURDU. HMM, ECM KARIŞTIRICINIZ ONU BOZUYOR OLABİLİR. O KARIŞTIRICILARI BİR SÜRE KULLANMASANIZ İYİ OLUR.",
["Ne?!! FBI şefini elinizden mi kaçırdınız? Olay yerinden gitmiş! Geri de gelmeyecek. B planına geçmek gerek."] = "NE?!! FBI ŞEFİNİ ELİNİZDEN Mİ KAÇIRDINIZ? OLAY YERİNDEN GİTMİŞ! GERİ DE GELMEYECEK. B PLANINA GEÇMEK GEREK.",
["Neden Kaşık Kullanmıyoruz?"] = "NEDEN KAŞIK KULLANMIYORUZ?",
["Neden ateş ettiniz? ECM Karıştırıcı kullanmanızı söylemiştim..."] = "NEDEN ATEŞ ETTİNİZ? ECM KARIŞTIRICI KULLANMANIZI SÖYLEMİŞTİM...",
["Neden bahsettiğinizi bilmiyorum!"] = "NEDEN BAHSETTİĞİNİZİ BİLMİYORUM!",
["Neden bazıları dünyanın yanışını izlemeyi sever? Ateş onlarla konuşur mu? En karanlık sırlarını doğrular mı? Öyleyse ateşin ne hikâyeler anlatabileceğini hayal et..."] = "NEDEN BAZILARI DÜNYANIN YANIŞINI İZLEMEYİ SEVER? ATEŞ ONLARLA KONUŞUR MU? EN KARANLIK SIRLARINI DOĞRULAR MI? ÖYLEYSE ATEŞİN NE HİKÂYELER ANLATABİLECEĞİNİ HAYAL ET...",
["Neden bu kadar geciktiniz?"] = "NEDEN BU KADAR GECİKTİNİZ?",
["Neden bu kadar uzun sürüyor?..."] = "NEDEN BU KADAR UZUN SÜRÜYOR?...",
["Neden bu kadar önemli olduğunu anlamaya başlıyorum, ha?"] = "NEDEN BU KADAR ÖNEMLİ OLDUĞUNU ANLAMAYA BAŞLIYORUM, HA?",
["Neden buradayız? Neler oluyor?"] = "NEDEN BURADAYIZ? NELER OLUYOR?",
["Neden dünyanın sonu gelmiş gibi hissediyorum lan?"] = "NEDEN DÜNYANIN SONU GELMİŞ GİBİ HİSSEDİYORUM LAN?",
["Neden hep geveze hücre arkadaşları bana düşüyor...?"] = "NEDEN HEP GEVEZE HÜCRE ARKADAŞLARI BANA DÜŞÜYOR...?",
["Neden hep zor olmak zorunda? Daireye bakın... Belki bilgiler onlardadır... Güvenli bir yerde."] = "NEDEN HEP ZOR OLMAK ZORUNDA? DAİREYE BAKIN... BELKİ BİLGİLER ONLARDADIR... GÜVENLİ BİR YERDE.",
["Neden hâlâ dışarıdasınız?"] = "NEDEN HÂLÂ DIŞARIDASINIZ?",
["Neden hâlâ oradasınız?"] = "NEDEN HÂLÂ ORADASINIZ?",
["Neden hâlâ silah laboratuvarında değilsiniz?"] = "NEDEN HÂLÂ SİLAH LABORATUVARINDA DEĞİLSİNİZ?",
["Neden içeridesin?"] = "NEDEN İÇERİDESİN?",
["Neden ki?"] = "NEDEN Kİ?",
["Neden kulaklığımdan testere sesi gelmiyor?"] = "NEDEN KULAKLIĞIMDAN TESTERE SESİ GELMİYOR?",
["Neden o kapıyı hâlâ delmiyorsunuz?"] = "NEDEN O KAPIYI HÂLÂ DELMİYORSUNUZ?",
["Neden olmasın? Etkili!"] = "NEDEN OLMASIN? ETKİLİ!",
