["Nereye gidiyor? Çamaşır odasına mı? Takip edin sizi aptallar!"] = "NEREYE GİDİYOR? ÇAMAŞIR ODASINA MI? TAKİP EDİN SİZİ APTALLAR!",
["New England'da yapılacak bir müzayedede bize gereken bir şey bulunduğuna dair ihbar aldık."] = "NEW ENGLAND'DA YAPILACAK BİR MÜZAYEDEDE BİZE GEREKEN BİR ŞEY BULUNDUĞUNA DAİR İHBAR ALDIK.",
["New York Meselesi"] = "NEW YORK MESELESİ",
