["O mücevherleri çantalayın."] = "O MÜCEVHERLERİ ÇANTALAYIN.",
["O nakil araçlarını açın!"] = "O NAKİL ARAÇLARINI AÇIN!",
["O nakil araçlarını bulun."] = "O NAKİL ARAÇLARINI BULUN.",
["O nakil araçlarını testereyle açın!"] = "O NAKİL ARAÇLARINI TESTEREYLE AÇIN!",
["O nakliye markası ordunun paravanı. O vagonları bulursanız baskı kalıplarını bulursunuz."] = "O NAKLİYE MARKASI ORDUNUN PARAVANI. O VAGONLARI BULURSANIZ BASKI KALIPLARINI BULURSUNUZ.",
["O ne?"] = "O NE?",
