["O parçaları alın soyguncular."] = "O PARÇALARI ALIN SOYGUNCULAR.",
["O patlama Hoxton'ı fena sarsmış olmalı. Biraz yürüsün, kendine gelir."] = "O PATLAMA HOXTON'I FENA SARSMIŞ OLMALI. BİRAZ YÜRÜSÜN, KENDİNE GELİR.",
["O patlamayı bütün tesis duydu. "] = "O PATLAMAYI BÜTÜN TESİS DUYDU. ",
