["O sandıkları açacak bir şey arayın."] = "O SANDIKLARI AÇACAK BİR ŞEY ARAYIN.",
["O sandıkları açmanız gerekiyor."] = "O SANDIKLARI AÇMANIZ GEREKİYOR.",
["O sarhoş moruğa kahve yapacak vakit yok. Güvende tutun. Şimdi tahliye gönderiyorum."] = "O SARHOŞ MORUĞA KAHVE YAPACAK VAKİT YOK. GÜVENDE TUTUN. ŞİMDİ TAHLİYE GÖNDERİYORUM.",
["O savaş başlıkları çok ağır. Taşımak için forkliftleri kullanın."] = "O SAVAŞ BAŞLIKLARI ÇOK AĞIR. TAŞIMAK İÇİN FORKLİFTLERİ KULLANIN.",
