["O senin sorumluluğundaydı!"] = "O SENİN SORUMLULUĞUNDAYDI!",
["O sersem kesin yeterince biliyor."] = "O SERSEM KESİN YETERİNCE BİLİYOR.",
["O sersemi bir şekilde oradan çıkarmamız gerekecek. Bir fikrim var."] = "O SERSEMİ BİR ŞEKİLDE ORADAN ÇIKARMAMIZ GEREKECEK. BİR FİKRİM VAR.",
