["O testere pek güvenilir görünmüyor, gözünüz üzerinde olsun."] = "O TESTERE PEK GÜVENİLİR GÖRÜNMÜYOR, GÖZÜNÜZ ÜZERİNDE OLSUN.",
["O testereler çalışır kalsın. Biri sıkışırsa hemen düzeltin. Sonsuza kadar kalamayız."] = "O TESTERELER ÇALIŞIR KALSIN. BİRİ SIKIŞIRSA HEMEN DÜZELTİN. SONSUZA KADAR KALAMAYIZ.",
["O testerelerin kesmeye devam etmesini sağlayın."] = "O TESTERELERİN KESMEYE DEVAM ETMESİNİ SAĞLAYIN.",
["O testereyi almayı unutmayın."] = "O TESTEREYİ ALMAYI UNUTMAYIN.",
["O testereyi bulmanız gerek, dostlar."] = "O TESTEREYİ BULMANIZ GEREK, DOSTLAR.",
["O testereyi bulun! Buralarda bir yerde olmalı. Kütüklerin etrafına bakın."] = "O TESTEREYİ BULUN! BURALARDA BİR YERDE OLMALI. KÜTÜKLERİN ETRAFINA BAKIN.",
